from pathlib import Path
import json, html

root=Path(__file__).parent
doc=json.loads((root/'source-copy.json').read_text())
p=[x['text'] for x in doc['paragraphs']]
e=html.escape
def original(i,tag='p',cls=''):
    return f'<{tag} class="{cls}" data-source-index="{i}">{e(p[i])}</{tag}>'
links=['3Dmj37HN9P','XKDuNIpGcJ','0v2RU36hKl','VzgzdeZkis','Je0ewkaRum']
