authors=[]
for name,file,i in [('Аня Кухарева','anya',6),('Дина Иванова','dina',7),('Анастасия Хачатурова','anastasia',8)]:
    authors.append(f'<article class="author author-{file}"><div class="portrait-wrap"><img class="portrait" src="assets/{file}.webp" alt="{name}" width="700" height="{849 if file=="anastasia" else 702 if file=="dina" else 700}" loading="lazy"><span class="tape" aria-hidden="true"></span></div><h3>{name}</h3>{original(i,cls="author-bio")}</article>')

